'use strict';
const fs=require('node:fs'),test=require('node:test'),assert=require('node:assert/strict'),crypto=require('node:crypto'),P=require('./policy.cjs'),F=require('./fixtures.cjs'),Fail=require('./failed-operation-c0a.cjs');
const ANCESTOR='C:/Users/runge/.nevermonday-secrets/ios16-protected-github-macos-context-v2-20261006';
test('all235 frozen context-V2 public ancestors are held with exact row identity',()=>{const rows=JSON.parse(fs.readFileSync(__dirname+'/source-dependencies.json')),rb=fs.readFileSync(ANCESTOR+'/source-review.json'),r=JSON.parse(rb),expected=[...r.sourceDependencies,...r.files.map(x=>({...x,file:ANCESTOR+'/'+x.file})),{file:ANCESTOR+'/source-review.json',bytes:rb.length,sha256:P.sha(rb)}];assert.equal(P.sha(rb),'9fb7672a108f76ce3d0d85d39b100ab1e289d33916ea33a3515cfeb1d3c87048');assert.equal(rows.length,295);for(const row of expected)assert.ok(rows.some(v=>JSON.stringify(v)===JSON.stringify(row)));});
test('every original accepting byte before diagnostic helper remains identical',()=>{const old=fs.readFileSync(ANCESTOR+'/native-audit.py','utf8'),current=fs.readFileSync(__dirname+'/native-audit.py','utf8');const start=current.indexOf('# BEGIN signed runtime configuration proof'),end=current.indexOf('# END signed runtime configuration proof.')+'# END signed runtime configuration proof.\n\n'.length;assert.ok(start>0&&end>start);let restored=current.slice(0,start)+current.slice(end);const changed="bundle=z.read(app+'main.jsbundle'); archive_runtime_proof(bundle, names, verified, app, z.getinfo, z.read)",original="bundle=z.read(app+'main.jsbundle'); require(bundle[:8] == bytes.fromhex('c61fbc03c103191f') and API in bundle and b'https://api.nevermonday.dk/api/mobile/v1' not in bundle)";assert.equal(restored.split(changed).length,2);restored=restored.replace(changed,original).replace('runtime_config_preflight(names, app, z.getinfo); ','');assert.equal(restored.split('def failure_projection(error):')[0],old.split("if __name__=='__main__':")[0]);});
test('both failed build operations remain refused before any source/export/build',()=>{for(const id of ['004dcd70-4e30-4ef6-97a0-47b984e6b131',Fail.OLD_ID]){const a=F.approval();a.operationId=id;a.environmentName='nm-ios16-'+id;assert.throws(()=>P.approval(a,F.NOW));}});
test('new independent operation remains accepted under exactly original600s window',()=>{const a=F.approval();assert.equal(P.approval(a,F.NOW).operationId,a.operationId);assert.throws(()=>P.approval(a,F.NOW+600000));});
test('c0a finite history has six exact descriptors and default import performs no I/O',()=>{assert.equal(Fail.ROWS.length,6);assert.equal(Fail.BASE,ANCESTOR+'/protected/'+Fail.OLD_ID);assert.deepEqual(Fail.ROWS.map(r=>r.file.slice(Fail.BASE.length+1)),['root-operation-once.json','github-dispatch-once.json','root-dispatch-proof.json','key-cleanup.json','root-cleanup-f1f33f24-252b-440a-879d-b5430293973b.json','root-authenticated-failure-proof.json']);assert.equal(new Set(Fail.ROWS.map(r=>r.file)).size,6);assert.throws(()=>Fail.hold());for(const r of Fail.ROWS)assert.match(r.sha256,/^[0-9a-f]{64}$/);});
test('exact history helper holds six fictional buffers and refuses before-after drift',()=>{const selected=new Map(Fail.ROWS.map((r,i)=>[r.file,Buffer.alloc(r.bytes,i+1)])),raw=fs.readFileSync(__dirname+'/failed-operation-c0a.cjs','utf8'),m={exports:{}},hash=()=>({update(b){this.b=Buffer.from(b);return this;},digest(){const row=Fail.ROWS.find(r=>selected.get(r.file).equals(this.b));return row?.sha256||crypto.createHash('sha256').update(this.b).digest('hex');}});new Function('require','module','exports',raw)(n=>{assert.equal(n,'node:crypto');return{createHash:hash};},m,m.exports);const reader=p=>Buffer.from(selected.get(p)),h=m.exports.hold(reader);assert.equal(h.size,6);m.exports.same(h,reader);selected.get(Fail.ROWS[3].file)[0]^=1;assert.throws(()=>m.exports.same(h,reader));});
test('history refuses malformed/changed buffers without reading any later descriptor',()=>{for(const mode of ['notBuffer','wrongSize','wrongHash']){const calls=[];assert.throws(()=>Fail.hold((p,n)=>{calls.push(p);return mode==='notBuffer'?'PRIVATE':Buffer.alloc(mode==='wrongSize'?n-1:n);}));assert.deepEqual(calls,[Fail.ROWS[0].file]);}});
